const items = $input.all();
const expanded = [];
for (const item of items) {
  const company = item.json;
  const platforms = company.ats_platforms || [];
  for (const platform of platforms) {
    expanded.push({ json: { company_id: company.id, company_name: company.name, company_domain: company.domain, ats_slug: company.ats_slug, ats_platform: platform } });
  }
}
return expanded;

const items = $input.all();
const results = [];

const companyMap = {};
for (const ei of $('Expand ATS Platforms').all()) {
  companyMap[ei.json.ats_slug] = { company_id: ei.json.company_id, company_name: ei.json.company_name };
}

for (const item of items) {
  const response = item.json;
  let jobs = [];

  const now = new Date();
  const day = now.getDay();
  const mondayOffset = day === 0 ? 6 : day - 1;
  const weekStart = new Date(now);
  weekStart.setDate(now.getDate() - mondayOffset);
  weekStart.setHours(0, 0, 0, 0);

  if (response.jobs && Array.isArray(response.jobs)) {
    const firstJob = response.jobs[0];
    if (firstJob && firstJob.absolute_url) {
      const slug = (firstJob.absolute_url.match(/boards\.greenhouse\.io\/([^\/]+)/) || [])[1] || '';
      const co = companyMap[slug] || {};
      jobs = response.jobs.map(j => ({
        company_id: co.company_id,
        company_name: co.company_name,
        ats_platform: 'greenhouse',
        job_id: String(j.id),
        title: j.title,
        location: j.location?.name || null,
        url: j.absolute_url,
        description: (j.content || '').replace(/<[^>]*>/g, '').substring(0, 1500),
        updated_at: j.updated_at
      }));
    } else if (firstJob && firstJob.jobUrl) {
      const slug = (firstJob.jobUrl.match(/jobs\.ashbyhq\.com\/([^\/]+)/) || [])[1] || '';
      const co = companyMap[slug] || {};
      jobs = response.jobs.map(j => ({
        company_id: co.company_id,
        company_name: co.company_name,
        ats_platform: 'ashby',
        job_id: String(j.id),
        title: j.title,
        location: j.locationName || null,
        url: j.jobUrl,
        description: (j.descriptionPlain || '').substring(0, 1500),
        updated_at: j.updatedAt || j.publishedDate
      }));
    }
  }

  for (const job of jobs) {
    if (!job.updated_at) continue;
    const jobDate = new Date(job.updated_at);
    if (jobDate >= weekStart) {
      results.push({ json: job });
    }
  }
}

return results;

const job = $('Split for Classify').item.json;
let category = 'unknown';

try {
  const raw = $input.item.json.output || $input.item.json.text || '';
  const cleaned = String(raw).toLowerCase().trim();
  const valid = ['infrastructure', 'security_compliance', 'data_ai', 'go_to_market', 'leadership', 'irrelevant'];

  if (valid.includes(cleaned)) {
    category = cleaned;
  } else {
    const match = cleaned.match(/(infrastructure|security_compliance|data_ai|go_to_market|leadership|irrelevant)/);
    if (match) {
      category = match[1];
    }
  }
} catch (e) {}

return { json: { ...job, category } };
